/*=----------------------------------------------------------------------=*\
   Use :Draws a circle object on the display with the center of the circle at the location X,Y
       :
       :Parameters for macro DrawCircle:
       :  X : X Coordinate for the center of the circle
       :  Y : Y coordinate for the center of the circle
       :  Radius : Radius of the circle specified in pixels
       :  Transparent : 0=Fill inside circle using background colour / 1=Draw outer circle only
       :  Solid : 0=Use Transparent Setting / 1=Fill with foreground colour
\*=----------------------------------------------------------------------=*/
void FCD_0ab21_gLCD_ST7567_SPI1__DrawCircle(MX_UINT16 FCL_X, MX_UINT16 FCL_Y, MX_UINT16 FCL_RADIUS, MX_UINT8 FCL_TRANSPARENT, MX_UINT8 FCL_SOLID)
{
  //Local variable definitions
  MX_SINT16 FCL_D;
  MX_SINT16 FCL_CURX;
  MX_SINT16 FCL_CURY;
  MX_UINT32 FCL_BGCOL;
  MX_UINT32 FCL_FGCOL;
  MX_UINT8 FCL_REP = (0x0);


  if (FCL_SOLID == 1)
  {  

  FCC_DrawCircle_A:
    ;

    FCL_D = 3 - (FCL_RADIUS << 1);

    FCL_CURX = 0;
    FCL_CURY = FCL_RADIUS;

    while (FCL_CURX <= FCL_CURY)
    {
      if (FCL_CURY > 0)
      {      

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X - FCL_CURY, FCL_Y + FCL_CURX, FCL_X + FCL_CURY, FCL_Y + FCL_CURX);

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X - FCL_CURY, FCL_Y - FCL_CURX, FCL_X + FCL_CURY, FCL_Y - FCL_CURX);

      // } else {

      }

      if (FCL_CURX > 0)
      {      

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X - FCL_CURX, FCL_Y - FCL_CURY, FCL_X + FCL_CURX, FCL_Y - FCL_CURY);

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X - FCL_CURX, FCL_Y + FCL_CURY, FCL_X + FCL_CURX, FCL_Y + FCL_CURY);

      // } else {

      }

      if (FCL_D < 0)
      {      

        FCL_D = FCL_D + ((FCL_CURX << 2) + 6);

      } else {

        FCL_D = FCL_D + (((FCL_CURX - FCL_CURY) << 2) + 10);

        FCL_CURY = FCL_CURY - 1;

      }

      FCL_CURX = FCL_CURX + 1;

    }

  } else {

    if (FCL_TRANSPARENT == 1)
    {    

    FCC_DrawCircle_B:
      ;

      FCL_D = 3 - (FCL_RADIUS << 1);

      FCL_CURX = 0;
      FCL_CURY = FCL_RADIUS;

      while (FCL_CURX <= FCL_CURY)
      {
        FCD_0ab21_gLCD_ST7567_SPI1__Plot(FCL_X + FCL_CURX, FCL_Y - FCL_CURY);

        FCD_0ab21_gLCD_ST7567_SPI1__Plot(FCL_X - FCL_CURX, FCL_Y - FCL_CURY);

        FCD_0ab21_gLCD_ST7567_SPI1__Plot(FCL_X + FCL_CURY, FCL_Y - FCL_CURX);

        FCD_0ab21_gLCD_ST7567_SPI1__Plot(FCL_X - FCL_CURY, FCL_Y - FCL_CURX);

        FCD_0ab21_gLCD_ST7567_SPI1__Plot(FCL_X + FCL_CURX, FCL_Y + FCL_CURY);

        FCD_0ab21_gLCD_ST7567_SPI1__Plot(FCL_X - FCL_CURX, FCL_Y + FCL_CURY);

        FCD_0ab21_gLCD_ST7567_SPI1__Plot(FCL_X + FCL_CURY, FCL_Y + FCL_CURX);

        FCD_0ab21_gLCD_ST7567_SPI1__Plot(FCL_X - FCL_CURY, FCL_Y + FCL_CURX);

        if (FCL_D < 0)
        {        

          FCL_D = FCL_D + ((FCL_CURX << 2) + 6);

        } else {

          FCL_D = FCL_D + (((FCL_CURX - FCL_CURY) << 2) + 10);

          FCL_CURY = FCL_CURY - 1;

        }

        FCL_CURX = FCL_CURX + 1;

      }

    } else {

      FCL_FGCOL = FCV_0ab21_gLCD_ST7567_SPI1__FOREGROUND_COL_VAR;
      FCL_BGCOL = FCV_0ab21_gLCD_ST7567_SPI1__BACKGROUND_COL_VAR;

      FCV_0ab21_gLCD_ST7567_SPI1__FOREGROUND_COL_VAR = FCL_BGCOL;

      FCL_REP = 1;

      goto FCC_DrawCircle_A;

    }

  }

  if (FCL_REP == 1)
  {  

    FCL_REP = FCL_REP + 1;

    FCV_0ab21_gLCD_ST7567_SPI1__FOREGROUND_COL_VAR = FCL_FGCOL;

    goto FCC_DrawCircle_B;

  // } else {

  }

}

/*=----------------------------------------------------------------------=*\
   Use :Parameters for macro Write_Command:
       :  Command : MX_UINT8
\*=----------------------------------------------------------------------=*/
void FCD_0ab21_gLCD_ST7567_SPI1__Write_Command(MX_UINT8 FCL_COMMAND)
{

  SET_PORT_PIN(A, 3, 0);
  SET_PORT_PIN(A, 2, 0);

  for (FCLV_LOOP7=0; (FCLV_LOOP7)<(8); (FCLV_LOOP7)++)
  {
    if (FCL_COMMAND & 0x80)
    {    

      SET_PORT_PIN(G, 8, 1);

    } else {

      SET_PORT_PIN(G, 8, 0);

    }

#if 0 // Disabled code
    FCI_DELAYBYTE_US(1);

#endif // Disabled code

    SET_PORT_PIN(G, 6, 0);

    FCL_COMMAND = FCL_COMMAND << 1;

#if 0 // Disabled code
    FCI_DELAYBYTE_US(1);

#endif // Disabled code

    SET_PORT_PIN(G, 6, 1);

  }

  SET_PORT_PIN(A, 2, 1);

}

/*=----------------------------------------------------------------------=*\
   Use :Draws a rectangle with rounded corners
       :
       :Parameters for macro DrawRoundedRectangle:
       :  X1 : MX_UINT16
       :  Y1 : MX_UINT16
       :  X2 : MX_UINT16
       :  Y2 : MX_UINT16
       :  Radius : MX_UINT16
       :  Transparent : Chooses the transparency of the box - 0 = Box contains background colour, 1 = Box contains previous pixel data.
       :  Solid : Chooses to fill the box with colour - 0 = Box contains transparency data, 1 = Box contains foreground colour.
\*=----------------------------------------------------------------------=*/
void FCD_0ab21_gLCD_ST7567_SPI1__DrawRoundedRectangle(MX_UINT16 FCL_X1, MX_UINT16 FCL_Y1, MX_UINT16 FCL_X2, MX_UINT16 FCL_Y2, MX_UINT16 FCL_RADIUS, MX_UINT8 FCL_TRANSPARENT, MX_UINT8 FCL_SOLID)
{
  //Local variable definitions
  MX_SINT16 FCL_G;
  MX_SINT16 FCL_HEIGHT;
  MX_SINT16 FCL_OXX1 = (0);
  MX_SINT16 FCL_OXX2 = (0);
  MX_SINT16 FCL_R;
  MX_SINT16 FCL_WIDTH;
  MX_SINT16 FCL_XX1;
  MX_SINT16 FCL_XX2;
  MX_SINT16 FCL_Y;
  MX_UINT16 FCL_COLSAVE16;


  FCL_WIDTH = FCL_X2 - FCL_X1;
  FCL_HEIGHT = FCL_Y2 - FCL_Y1;

  FCL_Y = -FCL_RADIUS;

  if (FCL_SOLID)
  {  

    while (FCL_Y <= 0)
    {
      FCL_R = flt_round(float32_sqrt(flt_fromi(FCL_RADIUS * FCL_RADIUS - FCL_Y * FCL_Y)));
      FCL_XX1 = FCL_X1 + FCL_R;
      FCL_XX2 = FCL_X1 - FCL_R;
      FCL_XX1 = FCL_XX1 + FCL_WIDTH - FCL_RADIUS;
      FCL_XX2 = FCL_XX2 + FCL_RADIUS;
      FCL_G = FCL_Y1 - FCL_Y + FCL_HEIGHT;

      FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_XX2, FCL_G - FCL_RADIUS, FCL_XX1, FCL_G - FCL_RADIUS);

      FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_XX2, FCL_Y1 + FCL_Y + FCL_RADIUS, FCL_XX1, FCL_Y1 + FCL_Y + FCL_RADIUS);

      FCL_Y = FCL_Y + 1;

    }

    if ((FCL_RADIUS >> 1) < (FCL_Y2 - FCL_Y1))
    {    

      FCD_0ab21_gLCD_ST7567_SPI1__DrawRectangle(FCL_X1, FCL_Y1 + FCL_RADIUS, FCL_X2, FCL_Y2 - FCL_RADIUS, FCL_TRANSPARENT, FCL_SOLID);

    // } else {

    }

  } else {

    while (FCL_Y <= 0)
    {
      FCL_R = flt_round(float32_sqrt(flt_fromi((FCL_RADIUS * FCL_RADIUS) - (FCL_Y * FCL_Y))));
      FCL_XX1 = FCL_X1 + FCL_R;
      FCL_XX2 = FCL_X1 - FCL_R;
      FCL_XX1 = FCL_XX1 + FCL_WIDTH - FCL_RADIUS;
      FCL_XX2 = FCL_XX2 + FCL_RADIUS;
      FCL_G = FCL_Y1 - FCL_Y + FCL_HEIGHT;

      if (FCL_Y == -FCL_RADIUS)
      {      

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_XX2, FCL_G - FCL_RADIUS, FCL_XX1, FCL_G - FCL_RADIUS);

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_XX2, FCL_Y1 + FCL_Y + FCL_RADIUS, FCL_XX1, FCL_Y1 + FCL_Y + FCL_RADIUS);

        FCL_OXX2 = FCL_XX2;
        FCL_OXX1 = FCL_XX1;

      } else {

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_XX2, FCL_G - FCL_RADIUS, FCL_OXX2, FCL_G - FCL_RADIUS);

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_XX1, FCL_G - FCL_RADIUS, FCL_OXX1, FCL_G - FCL_RADIUS);

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_XX2, FCL_Y1 + FCL_Y + FCL_RADIUS, FCL_OXX2, FCL_Y1 + FCL_Y + FCL_RADIUS);

        FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_XX1, FCL_Y1 + FCL_Y + FCL_RADIUS, FCL_OXX1, FCL_Y1 + FCL_Y + FCL_RADIUS);

        if (FCL_TRANSPARENT == 0)
        {        

          FCL_COLSAVE16 = FCV_0ab21_gLCD_ST7567_SPI1__FOREGROUND_COL_VAR;

          FCV_0ab21_gLCD_ST7567_SPI1__FOREGROUND_COL_VAR = FCV_0ab21_gLCD_ST7567_SPI1__BACKGROUND_COL_VAR;

          FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_OXX2 + 1, FCL_G - FCL_RADIUS, FCL_OXX1 - 1, FCL_G - FCL_RADIUS);

          FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_OXX2 + 1, FCL_Y1 + FCL_Y + FCL_RADIUS, FCL_OXX1 - 1, FCL_Y1 + FCL_Y + FCL_RADIUS);

          FCV_0ab21_gLCD_ST7567_SPI1__FOREGROUND_COL_VAR = FCL_COLSAVE16;

        // } else {

        }

        FCL_OXX2 = FCL_XX2;
        FCL_OXX1 = FCL_XX1;

      }

      FCL_Y = FCL_Y + 1;

    }

    if ((FCL_RADIUS >> 1) < (FCL_Y2 - FCL_Y1))
    {    

      FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X1, FCL_Y1 + FCL_RADIUS, FCL_X1, FCL_Y2 - FCL_RADIUS);

      FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X2, FCL_Y1 + FCL_RADIUS, FCL_X2, FCL_Y2 - FCL_RADIUS);

    // } else {

    }

    if (FCL_TRANSPARENT == 0)
    {    

      FCL_COLSAVE16 = FCV_0ab21_gLCD_ST7567_SPI1__FOREGROUND_COL_VAR;

      FCV_0ab21_gLCD_ST7567_SPI1__FOREGROUND_COL_VAR = FCV_0ab21_gLCD_ST7567_SPI1__BACKGROUND_COL_VAR;

      if ((FCL_RADIUS >> 1) < (FCL_Y2 - FCL_Y1))
      {      

        FCD_0ab21_gLCD_ST7567_SPI1__DrawRectangle(FCL_X1 + 1, FCL_Y1 + FCL_RADIUS + 1, FCL_X2 - 1, FCL_Y2 - FCL_RADIUS - 1, FCL_TRANSPARENT, FCL_SOLID);

      // } else {

      }

      FCV_0ab21_gLCD_ST7567_SPI1__FOREGROUND_COL_VAR = FCL_COLSAVE16;

    // } else {

    }

  }

}

