/*=----------------------------------------------------------------------=*\
   Use :Runs a short forward and reverse test, measures encoder balance, and saves motor trim values to EEPROM for this robot.
\*=----------------------------------------------------------------------=*/
void FCM_LogoCalibrateMotors()
{
  //Local variable definitions
  MX_UINT8 FCL_DONE = (0x0);
  MX_UINT32 FCL_AVG;
  MX_UINT16 FCL_ENCL;
  MX_UINT16 FCL_ENCR;
  MX_FLOAT FCL_FCALC;


  // Stop motors
  FCM_SetMotors(0, 0);

  // Settle before calibration
  FCI_DELAYBYTE_MS(200);

  // Reset trim defaults
  FCV_TRIMFWDL = 1.0;
  FCV_TRIMFWDR = 1.0;
  FCV_TRIMREVL = 1.0;
  FCV_TRIMREVR = 1.0;

  // Reset encoders for forward test
  FCV_ENCCOUNT[0] = 0;
  FCV_ENCCOUNT[1] = 0;

  // Drive forward calibration
  FCM_SetMotors(FCV_LOGOSPEED, FCV_LOGOSPEED);

  // Calculation
  FCL_DONE = 0;

  // Forward calibration loop
  while (FCL_DONE == 0)
  {
    // Delay
    FCI_DELAYBYTE_MS(10);

    // Calculation
    FCL_AVG = (FCV_ENCCOUNT[0] + FCV_ENCCOUNT[1]) / 2;

    // Forward test complete?
    if (FCL_AVG >= 80)
    {    

      // Calculation
      FCL_DONE = 1;

    // } else {

    }

  }

  // Stop after forward test
  FCM_SetMotors(0, 0);

  // Settle after forward test
  FCI_DELAYBYTE_MS(150);

  // Read forward encoder result
  FCL_ENCL = FCV_ENCCOUNT[0];
  FCL_ENCR = FCV_ENCCOUNT[1];

  // Valid forward encoder data?
  if (FCL_ENCR > 10)
  {  

    // Compute forward right trim
    FCL_FCALC = flt_div(flt_fromi(FCL_ENCL), flt_fromi(FCL_ENCR));
    FCV_TRIMFWDR = FCL_FCALC;

    // Clamp forward right trim high
    if (flt_gt(FCV_TRIMFWDR, 1.25))
    {    

      // Calculation
      FCV_TRIMFWDR = 1.25;

    // } else {

    }

    // Clamp forward right trim low
    if (flt_lt(FCV_TRIMFWDR, 0.75))
    {    

      // Calculation
      FCV_TRIMFWDR = 0.75;

    // } else {

    }

  // } else {

  }

  // Reset encoders for reverse test
  FCV_ENCCOUNT[0] = 0;
  FCV_ENCCOUNT[1] = 0;

  // Drive reverse calibration
  FCM_SetMotors(-FCV_LOGOSPEED, -FCV_LOGOSPEED);

  // Calculation
  FCL_DONE = 0;

  // Reverse calibration loop
  while (FCL_DONE == 0)
  {
    // Delay
    FCI_DELAYBYTE_MS(10);

    // Calculation
    FCL_AVG = (FCV_ENCCOUNT[0] + FCV_ENCCOUNT[1]) / 2;

    // Reverse test complete?
    if (FCL_AVG >= 80)
    {    

      // Calculation
      FCL_DONE = 1;

    // } else {

    }

  }

  // Stop after reverse test
  FCM_SetMotors(0, 0);

  // Settle after reverse test
  FCI_DELAYBYTE_MS(150);

  // Read reverse encoder result
  FCL_ENCL = FCV_ENCCOUNT[0];
  FCL_ENCR = FCV_ENCCOUNT[1];

  // Valid reverse encoder data?
  if (FCL_ENCR > 10)
  {  

    // Compute reverse right trim
    FCL_FCALC = flt_div(flt_fromi(FCL_ENCL), flt_fromi(FCL_ENCR));
    FCV_TRIMREVR = FCL_FCALC;

    // Clamp reverse right trim high
    if (flt_gt(FCV_TRIMREVR, 1.25))
    {    

      // Calculation
      FCV_TRIMREVR = 1.25;

    // } else {

    }

    // Clamp reverse right trim low
    if (flt_lt(FCV_TRIMREVR, 0.75))
    {    

      // Calculation
      FCV_TRIMREVR = 0.75;

    // } else {

    }

  // } else {

  }

  // Save forward left trim
  FCM_SetEEFloat(30, FCV_TRIMFWDL);

  // Save forward right trim
  FCM_SetEEFloat(40, FCV_TRIMFWDR);

  // Save reverse left trim
  FCM_SetEEFloat(50, FCV_TRIMREVL);

  // Save reverse right trim
  FCM_SetEEFloat(60, FCV_TRIMREVR);

  // Mark calibration valid
  FCD_0ee91_flasheeprom1__Write(20, 0);

}

