/*=----------------------------------------------------------------------=*\
   Use :
\*=----------------------------------------------------------------------=*/
void FCM_BattMon()
{
  //Local variable definitions
  #define FCLsz_CMD 20
  MX_CHAR FCL_CMD[FCLsz_CMD];
  MX_FLOAT FCL_FVAR;
  MX_UINT8 FCL_USB;
  MX_UINT8 FCL_BATTPERCENT;


  // Call Component Macro
  FCL_FVAR = FCM_ReadBattery();

  // Decision
  if (flt_lt(FCL_FVAR, 3.5))
  {  

    // Call Component Macro
    FCD_0ab21_gLCD_ST7567_SPI1__Print("!BATT LOW!", 11, 34, 16, 0, 0);

    // Call Component Macro
    FCD_0ab21_gLCD_ST7567_SPI1__Print("Please Recharge", 16, 19, 24, 0, 0);

    // Loop
    while (1)
    {
    }

  } else {

    // Call Component Macro
    FCL_USB = FCD_08833_USBSwitch__ReadState();

    // Decision
    if (FCL_USB)
    {    

      // Calculation
      FCL_FVAR = flt_sub(FCL_FVAR, 3.5);
      FCL_FVAR = flt_mul(FCL_FVAR, 125.0);

      // Calculation
      FCI_SCOPY("Charge:  ",10, FCL_CMD,FCLsz_CMD);

    } else {

      // Calculation
      FCL_FVAR = flt_sub(FCL_FVAR, 3.5);
      FCL_FVAR = flt_mul(FCL_FVAR, 166.66);

      // Calculation
      FCI_SCOPY("Battery: ",10, FCL_CMD,FCLsz_CMD);

    }

    // Calculation
    FCL_BATTPERCENT = flt_toi(FCL_FVAR);

    // Decision
    if (FCL_BATTPERCENT > 100)
    {    

      // Calculation
      FCL_BATTPERCENT = 100;

    // } else {

    }

    // Calculation
    {
    MX_CHAR FCI_TMP_STR[MX_MAX_TMPSTR_SIZE];
    FCI_SHEAD(FCL_CMD,FCLsz_CMD, FCI_TOSTRING(FCL_BATTPERCENT, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE),20, FCL_CMD,20);
    FCI_SHEAD(FCL_CMD,FCLsz_CMD, "%  ",4, FCL_CMD,20);
    }

    // Call Component Macro
    FCD_0ab21_gLCD_ST7567_SPI1__Print(FCL_CMD, FCLsz_CMD, 25, 16, 0, 0);

  }

  //Local variable definitions
  #undef FCLsz_CMD
}

/*=----------------------------------------------------------------------=*\
   Use :Simplified Logo movement using proportional encoder correction to keep motors in sync.
       :
       :Parameters for macro LogoProcess2:
       :  Left : Base power for left motor (can be negative)
       :  Right : Base power for right motor (can be negative)
       :  EncTarget : Target encoder count to travel (average of both wheels)
\*=----------------------------------------------------------------------=*/
void FCM_LogoProcess2(MX_SINT16 FCL_LEFT, MX_SINT16 FCL_RIGHT, MX_UINT32 FCL_ENCTARGET)
{
  //Local variable definitions
  MX_SINT16 FCL_LSP; // Current left motor speed
  MX_SINT16 FCL_RSP; // Current right motor speed
  MX_UINT16 FCL_ENCL; // Copy of left encoder count
  MX_UINT16 FCL_ENCR; // Copy of right encoder count
  MX_UINT32 FCL_AVG; // Average encoder count
  MX_SINT16 FCL_ERROR; // Encoder difference (EncL - EncR)
  MX_SINT16 FCL_CORRECTION; // Proportional correction value
  MX_UINT8 FCL_SPEEDSCALE = (0x64); // Speed scaling percentage for ramping (0-100)
  MX_UINT32 FCL_BRAKEDIST = (0x190); // Encoder counts over which to ramp down speed
  MX_UINT32 FCL_EFFBRAKE; // Effective braking distance used for this move
  MX_SINT16 FCL_BASEL; // Base (un-corrected) left speed after ramping
  MX_SINT16 FCL_BASER; // Base (un-corrected) right speed after ramping
  MX_SINT16 FCL_MAXSPEED = (100); // Maximum allowed motor speed
  MX_SINT16 FCL_MINPOWER = (22); // Minimum forward motor power to overcome static friction
  MX_SINT16 FCL_MINPOWERREV = (32); // Minimum reverse motor power (higher to match forward response)
  MX_SINT16 FCL_KICKL; // Kickstart power for left motor
  MX_SINT16 FCL_KICKR; // Kickstart power for right motor
  MX_UINT8 FCL_RAMPSTEP = (0x0); // Startup ramp step counter (0-25)
  MX_UINT8 FCL_ISTURN = (0x0); // 1 when motors run in opposite directions (pivot turn)
  MX_UINT8 FCL_ISREVERSE = (0x0); // 1 when both motors drive backward
  MX_SINT16 FCL_ERRORSUM; // Accumulated encoder error for straight-line trim
  MX_SINT16 FCL_TURNMIN; // Matched minimum power for both motors during pivot turns
  MX_SINT16 FCL_PREVERROR; // Previous encoder error for damping
  MX_SINT16 FCL_DERROR; // Rate of change of encoder error
  MX_SINT16 FCL_PREVLSP; // Previous left speed for slew limiting
  MX_SINT16 FCL_PREVRSP; // Previous right speed for slew limiting
  MX_UINT32 FCL_STOPTARGET; // Encoder target used to stop the move
  MX_SINT16 FCL_FLOORFWD; // Scaled minimum forward power for current speed
  MX_SINT16 FCL_FLOORREV; // Scaled minimum reverse power for current speed
  MX_FLOAT FCL_TRIMCALC; // Temporary value for motor trim
  MX_UINT16 FCL_PREVENCL; // Previous left encoder for speed balance
  MX_UINT16 FCL_PREVENCR; // Previous right encoder for speed balance
  MX_UINT16 FCL_DELTAL; // Left encoder change this loop
  MX_UINT16 FCL_DELTAR; // Right encoder change this loop
  MX_UINT8 FCL_VELTGT; // Expected encoder counts per loop
  MX_UINT8 FCL_DONE = (0x0); // Loop exit flag


  // Ensure minimum encoder target
  if (FCL_ENCTARGET == 0)
  {  

    // Set minimum target
    FCL_ENCTARGET = 1;

  // } else {

  }

  // Default stop target
  FCL_STOPTARGET = FCL_ENCTARGET;

  // Decision
  if (0 == 1)
  {  

    // Ensure Motors Are Stopped
    FCM_SetMotors(0, 0);

  // } else {

  }

  // Reset Encoders and Initialise
  FCV_ENCCOUNT[0] = 0;
  FCV_ENCCOUNT[1] = 0;
  FCL_RAMPSTEP = 0;
  FCL_DONE = 0;
  FCL_PREVERROR = 0;
  FCL_ERRORSUM = 0;
  FCL_PREVENCL = 0;
  FCL_PREVENCR = 0;
  FCV_LOGOMOVE = 1;

  // Settle before move
  FCI_DELAYBYTE_MS(30);

  // Straight reverse move?
  if ((FCL_LEFT < 0) && (FCL_RIGHT < 0))
  {  

    // Mark as reverse straight
    FCL_ISREVERSE = 1;

    // Lead reverse stop to reduce overshoot
    if (FCL_STOPTARGET > 10)
    {    

      // Stop slightly early going backward
      FCL_STOPTARGET = (FCL_STOPTARGET * 19) / 20;

    // } else {

    }

  // } else {

  }

  // Calculation
  FCL_MAXSPEED = FCV_LOGOSPEED;

  // Left kickstart power
  if (FCL_LEFT == 0)
  {  

    // Calculation
    FCL_KICKL = 0;

  } else {

    // Decision
    if (FCL_LEFT >= 0)
    {    

      // Calculation
      FCL_KICKL = FCL_MINPOWER;

    } else {

      // Calculation
      FCL_KICKL = -FCL_MINPOWERREV;

    }

  }

  // Right kickstart power
  if (FCL_RIGHT == 0)
  {  

    // Calculation
    FCL_KICKR = 0;

  } else {

    // Decision
    if (FCL_RIGHT >= 0)
    {    

      // Calculation
      FCL_KICKR = FCL_MINPOWER;

    } else {

      // Calculation
      FCL_KICKR = -FCL_MINPOWERREV;

    }

  }

  // Turn move with opposite motor directions?
  if (((FCL_LEFT < 0) && (FCL_RIGHT > 0)) || ((FCL_LEFT > 0) && (FCL_RIGHT < 0)))
  {  

    // Mark as turn move
    FCL_ISTURN = 1;
    FCL_TURNMIN = FCL_MINPOWERREV;

    // Lead turn stop to reduce overshoot
    if (FCL_STOPTARGET > 5)
    {    

      // Stop slightly early on turns
      FCL_STOPTARGET = FCL_STOPTARGET - 5;

    } else {

      // Small turn early stop
      FCL_STOPTARGET = (FCL_STOPTARGET * 9) / 10;

    }

    // Use higher value for matched turn power
    if (FCL_MINPOWER > FCL_TURNMIN)
    {    

      // Calculation
      FCL_TURNMIN = FCL_MINPOWER;

    // } else {

    }

    // Matched kickstart for left motor
    if (FCL_LEFT > 0)
    {    

      // Calculation
      FCL_KICKL = FCL_TURNMIN;

    } else {

      // Decision
      if (FCL_LEFT < 0)
      {      

        // Calculation
        FCL_KICKL = -FCL_TURNMIN;

      // } else {

      }

    }

    // Matched kickstart for right motor
    if (FCL_RIGHT > 0)
    {    

      // Calculation
      FCL_KICKR = FCL_TURNMIN;

    } else {

      // Decision
      if (FCL_RIGHT < 0)
      {      

        // Calculation
        FCL_KICKR = -FCL_TURNMIN;

      // } else {

      }

    }

    // Pre-kickstart reverse left motor
    if (FCL_LEFT < 0)
    {    

      // Start reverse left early
      FCM_SetMotors(FCL_KICKL, 0);

      // Delay
      FCI_DELAYBYTE_MS(25);

    // } else {

    }

    // Pre-kickstart reverse right motor
    if (FCL_RIGHT < 0)
    {    

      // Start reverse right early
      FCM_SetMotors(0, FCL_KICKR);

      // Delay
      FCI_DELAYBYTE_MS(25);

    // } else {

    }

  // } else {

  }

  // Kickstart Motors
  FCM_SetMotors(FCL_KICKL, FCL_KICKR);

  // Initialise slew limiter
  FCL_PREVLSP = FCL_KICKL;
  FCL_PREVRSP = FCL_KICKR;

  // Control Loop
  while (FCL_DONE == 0)
  {
    // Copy Encoder Counts and Average
    FCL_ENCL = FCV_ENCCOUNT[0];
    FCL_ENCR = FCV_ENCCOUNT[1];
    FCL_AVG = (FCL_ENCL + FCL_ENCR) / 2;

    // Reached Target Distance?
    if (FCL_AVG >= FCL_STOPTARGET)
    {    

      // Stop Motors
      FCM_SetMotors(0, 0);

      // Set Done Flag
      FCL_DONE = 1;

    } else {

      // Default Speed Scale
      FCL_SPEEDSCALE = 100;

      // Have a valid distance target?
      if (FCL_ENCTARGET > 0)
      {      

        // Compute Effective Brake Distance
        FCL_EFFBRAKE = FCL_BRAKEDIST;

        // Decision
        if (FCL_ENCTARGET / 2 < FCL_EFFBRAKE)
        {        

          // Calculation
          FCL_EFFBRAKE = FCL_ENCTARGET / 2;

        // } else {

        }

        // Has a non-zero braking distance?
        if (FCL_EFFBRAKE > 0)
        {        

          // Within braking distance?
          if ((FCL_ENCTARGET > FCL_AVG) && ((FCL_ENCTARGET - FCL_AVG) <= FCL_EFFBRAKE))
          {          

            // Ramp Down SpeedScale
            FCL_SPEEDSCALE = ((FCL_ENCTARGET - FCL_AVG) * 100) / FCL_EFFBRAKE;

          // } else {

          }

        // } else {

        }

      // } else {

      }

      // Clamp SpeedScale High
      if (FCL_SPEEDSCALE > 100)
      {      

        // Limit SpeedScale High
        FCL_SPEEDSCALE = 100;

      // } else {

      }

      // Clamp SpeedScale Low
      if (FCL_SPEEDSCALE < 30)
      {      

        // Use higher brake floor on turns
        if (FCL_ISTURN == 1)
        {        

          // Limit SpeedScale Low on turn
          FCL_SPEEDSCALE = 50;

        } else {

          // Allow slower straight braking
          if (FCL_SPEEDSCALE < 10)
          {          

            // Limit SpeedScale Low on straight
            FCL_SPEEDSCALE = 10;

          // } else {

          }

        }

      // } else {

      }

      // Apply Ramping to Base Speeds
      FCL_BASEL = (FCL_LEFT * FCL_SPEEDSCALE) / 100;
      FCL_BASER = (FCL_RIGHT * FCL_SPEEDSCALE) / 100;

      // Startup ramp in progress?
      if (FCL_RAMPSTEP < 25)
      {      

        // Ramp left motor
        if (FCL_LEFT != 0)
        {        

          // Ramp BaseL from kickstart
          FCL_BASEL = FCL_KICKL + ((FCL_BASEL - FCL_KICKL) * FCL_RAMPSTEP) / 25;

        // } else {

        }

        // Ramp right motor
        if (FCL_RIGHT != 0)
        {        

          // Ramp BaseR from kickstart
          FCL_BASER = FCL_KICKR + ((FCL_BASER - FCL_KICKR) * FCL_RAMPSTEP) / 25;

        // } else {

        }

        // Next ramp step
        FCL_RAMPSTEP = FCL_RAMPSTEP + 1;

      // } else {

      }

      // Apply forward trim to left
      if (FCL_LEFT > 0)
      {      

        // Calculation
        FCL_TRIMCALC = flt_mul(flt_fromi(FCL_BASEL), FCV_TRIMFWDL);
        FCL_BASEL = flt_toi(FCL_TRIMCALC);

      } else {

        // Apply reverse trim to left
        if (FCL_LEFT < 0)
        {        

          // Calculation
          FCL_TRIMCALC = flt_mul(flt_fromi(FCL_BASEL), FCV_TRIMREVL);
          FCL_BASEL = flt_toi(FCL_TRIMCALC);

        // } else {

        }

      }

      // Apply forward trim to right
      if (FCL_RIGHT > 0)
      {      

        // Calculation
        FCL_TRIMCALC = flt_mul(flt_fromi(FCL_BASER), FCV_TRIMFWDR);
        FCL_BASER = flt_toi(FCL_TRIMCALC);

      } else {

        // Apply reverse trim to right
        if (FCL_RIGHT < 0)
        {        

          // Calculation
          FCL_TRIMCALC = flt_mul(flt_fromi(FCL_BASER), FCV_TRIMREVR);
          FCL_BASER = flt_toi(FCL_TRIMCALC);

        // } else {

        }

      }

      // Compute Error and Correction
      FCL_ERROR = FCL_ENCL - FCL_ENCR;
      FCL_DERROR = FCL_ERROR - FCL_PREVERROR;
      FCL_PREVERROR = FCL_ERROR;

      // Turn deadband only
      if ((FCL_ISTURN == 1) && (FCL_ERROR > -5) && (FCL_ERROR < 5))
      {      

        // Pivot encoders close enough
        FCL_CORRECTION = 0;

      } else {

        // Straight deadband only
        if ((FCL_ISTURN == 0) && (FCL_ERROR > -2) && (FCL_ERROR < 2))
        {        

          // Straight encoders close enough
          FCL_CORRECTION = 0;
          FCL_ERRORSUM = 0;

        } else {

          // Pivot turn sync
          if (FCL_ISTURN == 1)
          {          

            // PD correction for pivot turn
            FCL_CORRECTION = (FCL_ERROR / 10) + (FCL_DERROR / 6);

          } else {

            // Reverse straight sync
            if (FCL_ISREVERSE == 1)
            {            

              // Stronger PD for backward straight
              FCL_CORRECTION = (FCL_ERROR / 3) + (FCL_DERROR / 3);

            } else {

              // PD correction for forward straight
              FCL_CORRECTION = (FCL_ERROR / 4) + (FCL_DERROR / 4);

            }

          }

        }

      }

      // Add integral trim on straight moves
      if (FCL_ISTURN == 0)
      {      

        // Accumulate steady drift
        FCL_ERRORSUM = FCL_ERRORSUM + FCL_ERROR;

        // Limit integral high
        if (FCL_ERRORSUM > 40)
        {        

          // Calculation
          FCL_ERRORSUM = 40;

        // } else {

        }

        // Limit integral low
        if (FCL_ERRORSUM < -40)
        {        

          // Calculation
          FCL_ERRORSUM = -40;

        // } else {

        }

        // Apply integral correction
        FCL_CORRECTION = FCL_CORRECTION + (FCL_ERRORSUM / 10);

      // } else {

      }

      // Cap correction on turns
      if (FCL_ISTURN == 1)
      {      

        // Limit positive turn correction
        if (FCL_CORRECTION > 3)
        {        

          // Calculation
          FCL_CORRECTION = 3;

        // } else {

        }

        // Limit negative turn correction
        if (FCL_CORRECTION < -3)
        {        

          // Calculation
          FCL_CORRECTION = -3;

        // } else {

        }

      } else {

        // Limit positive straight correction
        if (FCL_CORRECTION > 10)
        {        

          // Calculation
          FCL_CORRECTION = 10;

        // } else {

        }

        // Limit negative straight correction
        if (FCL_CORRECTION < -10)
        {        

          // Calculation
          FCL_CORRECTION = -10;

        // } else {

        }

      }

      // Decision
      if (FCL_LEFT < 0)
      {      

        // Calculation
        FCL_LSP = FCL_BASEL + FCL_CORRECTION;

      } else {

        // Calculation
        FCL_LSP = FCL_BASEL - FCL_CORRECTION;

      }

      // Decision
      if (FCL_RIGHT < 0)
      {      

        // Calculation
        FCL_RSP = FCL_BASER - FCL_CORRECTION;

      } else {

        // Calculation
        FCL_RSP = FCL_BASER + FCL_CORRECTION;

      }

      // Encoder speed deltas
      FCL_DELTAL = FCL_ENCL - FCL_PREVENCL;
      FCL_DELTAR = FCL_ENCR - FCL_PREVENCR;
      FCL_PREVENCL = FCL_ENCL;
      FCL_PREVENCR = FCL_ENCR;

      // Cruise speed balance active?
      if ((FCL_RAMPSTEP >= 25) && (FCL_SPEEDSCALE > 40))
      {      

        // Balance left forward speed
        if (FCL_LEFT > 0)
        {        

          // Expected left counts
          FCL_VELTGT = FCL_BASEL / 6;

          // Left wheel too slow
          if ((FCL_VELTGT > 2) && (FCL_DELTAL + 1 < FCL_VELTGT))
          {          

            // Calculation
            FCL_LSP = FCL_LSP + 1;

          // } else {

          }

          // Left wheel too fast
          if ((FCL_VELTGT > 2) && (FCL_DELTAL > FCL_VELTGT + 2))
          {          

            // Calculation
            FCL_LSP = FCL_LSP - 1;

          // } else {

          }

        } else {

          // Balance left reverse speed
          if (FCL_LEFT < 0)
          {          

            // Expected left counts
            FCL_VELTGT = (0 - FCL_BASEL) / 6;

            // Left wheel too slow
            if ((FCL_VELTGT > 2) && (FCL_DELTAL + 1 < FCL_VELTGT))
            {            

              // Calculation
              FCL_LSP = FCL_LSP - 1;

            // } else {

            }

            // Left wheel too fast
            if ((FCL_VELTGT > 2) && (FCL_DELTAL > FCL_VELTGT + 2))
            {            

              // Calculation
              FCL_LSP = FCL_LSP + 1;

            // } else {

            }

          // } else {

          }

        }

        // Balance right forward speed
        if (FCL_RIGHT > 0)
        {        

          // Expected right counts
          FCL_VELTGT = FCL_BASER / 6;

          // Right wheel too slow
          if ((FCL_VELTGT > 2) && (FCL_DELTAR + 1 < FCL_VELTGT))
          {          

            // Calculation
            FCL_RSP = FCL_RSP + 1;

          // } else {

          }

          // Right wheel too fast
          if ((FCL_VELTGT > 2) && (FCL_DELTAR > FCL_VELTGT + 2))
          {          

            // Calculation
            FCL_RSP = FCL_RSP - 1;

          // } else {

          }

        } else {

          // Balance right reverse speed
          if (FCL_RIGHT < 0)
          {          

            // Expected right counts
            FCL_VELTGT = (0 - FCL_BASER) / 6;

            // Right wheel too slow
            if ((FCL_VELTGT > 2) && (FCL_DELTAR + 1 < FCL_VELTGT))
            {            

              // Calculation
              FCL_RSP = FCL_RSP - 1;

            // } else {

            }

            // Right wheel too fast
            if ((FCL_VELTGT > 2) && (FCL_DELTAR > FCL_VELTGT + 2))
            {            

              // Calculation
              FCL_RSP = FCL_RSP + 1;

            // } else {

            }

          // } else {

          }

        }

      // } else {

      }

      // Clamp LSP High
      if (FCL_LSP > FCL_MAXSPEED)
      {      

        // Limit LSP High
        FCL_LSP = FCL_MAXSPEED;

      // } else {

      }

      // Clamp LSP Low
      if (FCL_LSP < -FCL_MAXSPEED)
      {      

        // Limit LSP Low
        FCL_LSP = -FCL_MAXSPEED;

      // } else {

      }

      // Clamp RSP High
      if (FCL_RSP > FCL_MAXSPEED)
      {      

        // Limit RSP High
        FCL_RSP = FCL_MAXSPEED;

      // } else {

      }

      // Clamp RSP Low
      if (FCL_RSP < -FCL_MAXSPEED)
      {      

        // Limit RSP Low
        FCL_RSP = -FCL_MAXSPEED;

      // } else {

      }

      // Scale power floor with braking ramp
      FCL_FLOORFWD = (FCL_MINPOWER * FCL_SPEEDSCALE) / 100;
      FCL_FLOORREV = (FCL_MINPOWERREV * FCL_SPEEDSCALE) / 100;

      // Minimum scaled forward floor
      if (FCL_FLOORFWD < 8)
      {      

        // Calculation
        FCL_FLOORFWD = 8;

      // } else {

      }

      // Minimum scaled reverse floor
      if (FCL_FLOORREV < 8)
      {      

        // Calculation
        FCL_FLOORREV = 8;

      // } else {

      }

      // Matched minimum power during turns
      if (FCL_ISTURN == 1)
      {      

        // Floor left forward on turn
        if (FCL_LEFT > 0)
        {        

          // Decision
          if (FCL_LSP < FCL_TURNMIN)
          {          

            // Calculation
            FCL_LSP = FCL_TURNMIN;

          // } else {

          }

        // } else {

        }

        // Floor left reverse on turn
        if (FCL_LEFT < 0)
        {        

          // Decision
          if (FCL_LSP > -FCL_TURNMIN)
          {          

            // Calculation
            FCL_LSP = -FCL_TURNMIN;

          // } else {

          }

        // } else {

        }

        // Floor right forward on turn
        if (FCL_RIGHT > 0)
        {        

          // Decision
          if (FCL_RSP < FCL_TURNMIN)
          {          

            // Calculation
            FCL_RSP = FCL_TURNMIN;

          // } else {

          }

        // } else {

        }

        // Floor right reverse on turn
        if (FCL_RIGHT < 0)
        {        

          // Decision
          if (FCL_RSP > -FCL_TURNMIN)
          {          

            // Calculation
            FCL_RSP = -FCL_TURNMIN;

          // } else {

          }

        // } else {

        }

      } else {

        // Floor left motor forward
        if (FCL_LEFT > 0)
        {        

          // Prevent left forward stall
          if (FCL_LSP < FCL_FLOORFWD)
          {          

            // Calculation
            FCL_LSP = FCL_FLOORFWD;

          // } else {

          }

        // } else {

        }

        // Floor left motor reverse
        if (FCL_LEFT < 0)
        {        

          // Prevent left reverse stall
          if (FCL_LSP > -FCL_FLOORREV)
          {          

            // Calculation
            FCL_LSP = -FCL_FLOORREV;

          // } else {

          }

        // } else {

        }

        // Floor right motor forward
        if (FCL_RIGHT > 0)
        {        

          // Prevent right forward stall
          if (FCL_RSP < FCL_FLOORFWD)
          {          

            // Calculation
            FCL_RSP = FCL_FLOORFWD;

          // } else {

          }

        // } else {

        }

        // Floor right motor reverse
        if (FCL_RIGHT < 0)
        {        

          // Prevent right reverse stall
          if (FCL_RSP > -FCL_FLOORREV)
          {          

            // Calculation
            FCL_RSP = -FCL_FLOORREV;

          // } else {

          }

        // } else {

        }

      }

      // Smooth speed changes on turns
      if (FCL_ISTURN == 1)
      {      

        // Limit left speed increase
        if (FCL_LSP > (FCL_PREVLSP + 2))
        {        

          // Calculation
          FCL_LSP = FCL_PREVLSP + 2;

        // } else {

        }

        // Limit left speed decrease
        if (FCL_LSP < (FCL_PREVLSP - 2))
        {        

          // Calculation
          FCL_LSP = FCL_PREVLSP - 2;

        // } else {

        }

        // Limit right speed increase
        if (FCL_RSP > (FCL_PREVRSP + 2))
        {        

          // Calculation
          FCL_RSP = FCL_PREVRSP + 2;

        // } else {

        }

        // Limit right speed decrease
        if (FCL_RSP < (FCL_PREVRSP - 2))
        {        

          // Calculation
          FCL_RSP = FCL_PREVRSP - 2;

        // } else {

        }

      // } else {

      }

      // Store speeds for next slew step
      FCL_PREVLSP = FCL_LSP;
      FCL_PREVRSP = FCL_RSP;

      // Update Motors
      FCM_SetMotors(FCL_LSP, FCL_RSP);

      // Slower control loop on turns
      if (FCL_ISTURN == 1)
      {      

        // Delay
        FCI_DELAYBYTE_MS(15);

      } else {

        // Delay
        FCI_DELAYBYTE_MS(10);

      }

    }

  }

  // End Logo move
  FCV_LOGOMOVE = 0;

  // Settle after move
  FCI_DELAYBYTE_MS(100);

}

/*=----------------------------------------------------------------------=*\
   Use :Loads per-robot motor trim values from EEPROM
\*=----------------------------------------------------------------------=*/
void FCM_Prv_LoadMotorCal()
{

  // Load forward left trim
  FCV_TRIMFWDL = FCM_GetEEFloat(30);

  // Load forward right trim
  FCV_TRIMFWDR = FCM_GetEEFloat(40);

  // Load reverse left trim
  FCV_TRIMREVL = FCM_GetEEFloat(50);

  // Load reverse right trim
  FCV_TRIMREVR = FCM_GetEEFloat(60);

  // Validate forward left trim
  if ((flt_lt(FCV_TRIMFWDL, 0.75)) || (flt_gt(FCV_TRIMFWDL, 1.25)))
  {  

    // Calculation
    FCV_TRIMFWDL = 1.0;

  // } else {

  }

  // Validate forward right trim
  if ((flt_lt(FCV_TRIMFWDR, 0.75)) || (flt_gt(FCV_TRIMFWDR, 1.25)))
  {  

    // Calculation
    FCV_TRIMFWDR = 1.0;

  // } else {

  }

  // Validate reverse left trim
  if ((flt_lt(FCV_TRIMREVL, 0.75)) || (flt_gt(FCV_TRIMREVL, 1.25)))
  {  

    // Calculation
    FCV_TRIMREVL = 1.0;

  // } else {

  }

  // Validate reverse right trim
  if ((flt_lt(FCV_TRIMREVR, 0.75)) || (flt_gt(FCV_TRIMREVR, 1.25)))
  {  

    // Calculation
    FCV_TRIMREVR = 1.0;

  // } else {

  }

}

