/*=----------------------------------------------------------------------=*\
   Use :Writes a value to the 16-bit audio output buffer.
       :
       :Parameters for macro AudioAddToBuffer:
       :  Data : MX_UINT16
\*=----------------------------------------------------------------------=*/
void FCM_AudioAddToBuffer(MX_UINT16 FCL_DATA)
{

  // Decision
  if (FCV_AUDIOBITDEPTH == 16)
  {  

    // Call Component Macro
    FCD_02b22_CB_AUDIO__PutByte(FCL_DATA);

    // Call Component Macro
    FCD_02b22_CB_AUDIO__PutByte(FCL_DATA >> 8);

  } else {

    // Call Component Macro
    FCD_02b22_CB_AUDIO__PutByte(FCL_DATA);

  }

  // Calculation
  FCV_AUDIOSAMPLECOUNT = FCV_AUDIOSAMPLECOUNT + 1;

}

