/*=----------------------------------------------------------------------=*\
   Use :Checks to see if a line sensor is within the master threshold distance.
       :Returns 0 if the IR reading is below the threshold.
       :Returns 1 if the IR reading is greater than or equal to the threshold.
       :
       :Parameters for macro CheckLine:
       :  Sensor : Range: 0 to 1 - 0=Left, 1=Right
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_CheckLine(MX_UINT8 FCL_SENSOR)
{
  //Local variable definitions
  MX_UINT16 FCL_RET;
  MX_UINT8 FCR_RETVAL;


  // Call Macro
  FCL_RET = FCM_ReadLineSensor(FCL_SENSOR);

  // Decision
  if (FCL_RET >= 50)
  {  

    // Calculation
    FCR_RETVAL = 1;

  } else {

    // Calculation
    FCR_RETVAL = 0;

  }

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Allows control of the audio output functionality via the onboard speaker.
       :Data is loaded into the audio output buffer using the AddToBuffer function.
       :
       :Parameters for macro AudioStreamControl:
       :  Mode : 0=Off, 8=8-bit Mode, 16=16-bit Mode
       :  SampleRate : Sets the sample rate 0=8KHz, 1=16KHz
\*=----------------------------------------------------------------------=*/
void FCM_AudioStreamControl(MX_UINT8 FCL_MODE, MX_UINT8 FCL_SAMPLERATE)
{
  //Local variable definitions
  MX_UINT16 FCL_INTERRUPTRATE;


  // Decision
  if (FCL_MODE > 0)
  {  

    // Decision
    if (FCL_MODE & 1)
    {    

      // Calculation
      FCV_AUDIOBITDEPTH = FCL_MODE & 0x18;

      // Calculation
      FCV_AUDIOMODE = 1;

    } else {

      // Calculation
      FCV_AUDIOBITDEPTH = FCL_MODE;

      // Call Component Macro
      FC_CAL_PWM_Enable_1();

      // Call Component Macro
      FC_CAL_PWM_SetDuty10Bit_1(1024);

      // Calculation
      FCV_AUDIOMODE = 0;

    }

    // Call Component Macro
    FCD_02b22_CB_AUDIO__FlushBuffer();

    // Calculation
    FCV_AUDIOSAMPLECOUNT = 0;

    // Decision
    if (FCL_SAMPLERATE == 0)
    {    

      // 8KHz
      FCL_INTERRUPTRATE = 8750;

    } else {

      // 16KHz
      FCL_INTERRUPTRATE = 4375;

    }

    T9CON = ((T9CON & 0xfffd) | 0x8000);
    T9CON &= 0xff0f;
    PR9=FCL_INTERRUPTRATE-1;
    IEC3bits.T9IE = 1;

  } else {

    // Call Component Macro
    FC_CAL_PWM_Disable_1();

    IEC3bits.T9IE = 0;

  }

}

/*=----------------------------------------------------------------------=*\
   Use :Process the Logo movement
       :
       :Parameters for macro LogoProcess:
       :  Left : MX_SINT16
       :  Right : MX_SINT16
       :  EncTarget : MX_UINT32
\*=----------------------------------------------------------------------=*/
void FCM_LogoProcess(MX_SINT16 FCL_LEFT, MX_SINT16 FCL_RIGHT, MX_UINT32 FCL_ENCTARGET)
{
  //Local variable definitions
  MX_SINT16 FCL_LSP;
  MX_SINT16 FCL_RSP;
  MX_UINT8 FCL_DONE = (0x0);
  #define FCLsz_DIR 2
  MX_UINT8 FCL_DIR[FCLsz_DIR];
  #define FCLsz_ENCCOUNTOLD 2
  MX_UINT16 FCL_ENCCOUNTOLD[FCLsz_ENCCOUNTOLD];
  MX_UINT8 FCL_MODE;
  MX_UINT8 FCL_OLDMODE;
  MX_UINT8 FCL_COUNTER = (0x0);
  MX_UINT8 FCL_COUNTDOWN;


  // Decision
  if (0 == 1)
  {  

    // Ensure Motors Are Stopped
    FCM_SetMotors(0, 0);

  // } else {

  }

  // Decision
  if (FCL_ENCTARGET > 100)
  {  

    // Calculation
    FCL_COUNTDOWN = 50;

  } else {

    // Calculation
    FCL_COUNTDOWN = FCL_ENCTARGET / 3;

  }

  // Calculation
  FCV_LOGOMOVE = 1;

  // Decision
  if (FCL_LEFT >= 0)
  {  

    // Calculation
    FCL_DIR[0] = 1;

    // Calculation
    FCL_LSP = 15;

  } else {

    // Calculation
    FCL_DIR[0] = 0;

    // Calculation
    FCL_LSP = -15;

  }

  // Decision
  if (FCL_RIGHT >= 0)
  {  

    // Calculation
    FCL_DIR[1] = 1;

    // Calculation
    FCL_RSP = 15;

  } else {

    // Calculation
    FCL_DIR[1] = 0;

    // Calculation
    FCL_RSP = -15;

  }

  // Reset Encoder Counters
  FCV_ENCCOUNT[0] = 0;
  FCV_ENCCOUNT[1] = 0;

  // Calculation
  FCL_MODE = 0;
  FCL_OLDMODE = 10;
  FCL_COUNTER = 0;

  // Loop
  while (FCL_DONE == 0)
  {
    // Decision
    if ((FCV_ENCCOUNT[0] >= FCL_ENCTARGET) || (FCV_ENCCOUNT[1] >= FCL_ENCTARGET))
    {    

      // Brake
      FCM_SetMotors(0, 0);

      // Calculation
      FCL_DONE = 1;

    } else {

      // Start Motors
      FCM_SetMotors(FCL_LSP, FCL_RSP);

    }

    // Decision
    if (FCV_ENCCOUNT[0] > FCV_ENCCOUNT[1])
    {    

      //Comment:
      //Left Motor Too Fast, Right Motor Too Slow

      // Calculation
      FCL_MODE = 3;

      // Decision
      if (FCL_MODE != FCL_OLDMODE)
      {      

        // Calculation
        FCL_COUNTER = 0;

        // Decision
        if (FCL_DIR[0] == 1)
        {        

          // Decision
          if (FCL_LSP > 0)
          {          

            // Calculation
            FCL_LSP = FCL_LSP - 1;

          // } else {

          }

        } else {

          // Decision
          if (FCL_LSP < 0)
          {          

            // Calculation
            FCL_LSP = FCL_LSP + 1;

          // } else {

          }

        }

        // Decision
        if (FCL_DIR[1] == 1)
        {        

          // Decision
          if (FCL_RSP < FCV_LOGOSPEED)
          {          

            // Calculation
            FCL_RSP = FCL_RSP + 1;

          // } else {

          }

        } else {

          // Decision
          if (FCL_RSP > -FCV_LOGOSPEED)
          {          

            // Calculation
            FCL_RSP = FCL_RSP - 1;

          // } else {

          }

        }

      } else {

        // Calculation
        FCL_COUNTER = FCL_COUNTER + 1;

      }

    } else {

      // Decision
      if (FCV_ENCCOUNT[1] > FCV_ENCCOUNT[0])
      {      

        //Comment:
        //Right Motor Too Fast, Left Motor Too Slow

        // Calculation
        FCL_MODE = 2;

        // Decision
        if (FCL_MODE != FCL_OLDMODE)
        {        

          // Calculation
          FCL_COUNTER = 0;

          // Decision
          if (FCL_DIR[1] == 1)
          {          

            // Decision
            if (FCL_RSP > 0)
            {            

              // Calculation
              FCL_RSP = FCL_RSP - 1;

            // } else {

            }

          } else {

            // Decision
            if (FCL_RSP < 0)
            {            

              // Calculation
              FCL_RSP = FCL_RSP + 1;

            // } else {

            }

          }

          // Decision
          if (FCL_DIR[0] == 1)
          {          

            // Decision
            if (FCL_LSP < FCV_LOGOSPEED)
            {            

              // Calculation
              FCL_LSP = FCL_LSP + 1;

            // } else {

            }

          } else {

            // Decision
            if (FCL_LSP > -FCV_LOGOSPEED)
            {            

              // Calculation
              FCL_LSP = FCL_LSP - 1;

            // } else {

            }

          }

        } else {

          // Calculation
          FCL_COUNTER = FCL_COUNTER + 1;

        }

      } else {

        // Decision
        if ((FCV_ENCCOUNT[0] >= (FCL_ENCTARGET - FCL_COUNTDOWN)) || (FCV_ENCCOUNT[1] >= (FCL_ENCTARGET - FCL_COUNTDOWN)))
        {        

          //Comment:
          //Slow Down

          // Calculation
          FCL_MODE = 1;

          // Decision
          if (FCL_MODE != FCL_OLDMODE)
          {          

            // Calculation
            FCL_COUNTER = 0;

            // Decision
            if (FCL_DIR[0] == 1)
            {            

              // Decision
              if (FCL_LSP > 10)
              {              

                // Calculation
                FCL_LSP = FCL_LSP - 1;

              // } else {

              }

            } else {

              // Decision
              if (FCL_LSP < -10)
              {              

                // Calculation
                FCL_LSP = FCL_LSP + 1;

              // } else {

              }

            }

            // Decision
            if (FCL_DIR[1] == 1)
            {            

              // Decision
              if (FCL_RSP > 10)
              {              

                // Calculation
                FCL_RSP = FCL_RSP - 1;

              // } else {

              }

            } else {

              // Decision
              if (FCL_RSP < -10)
              {              

                // Calculation
                FCL_RSP = FCL_RSP + 1;

              // } else {

              }

            }

          } else {

            // Calculation
            FCL_COUNTER = FCL_COUNTER + 1;

          }

        } else {

          //Comment:
          //Speed Up

          // Calculation
          FCL_MODE = 0;

          // Decision
          if (FCL_MODE != FCL_OLDMODE)
          {          

            // Calculation
            FCL_COUNTER = 0;

            // Decision
            if (FCL_DIR[0] == 1)
            {            

              // Decision
              if (FCL_LSP < FCV_LOGOSPEED)
              {              

                // Calculation
                FCL_LSP = FCL_LSP + 1;

              // } else {

              }

            } else {

              // Decision
              if (FCL_LSP > -FCV_LOGOSPEED)
              {              

                // Calculation
                FCL_LSP = FCL_LSP - 1;

              // } else {

              }

            }

            // Decision
            if (FCL_DIR[1] == 1)
            {            

              // Decision
              if (FCL_RSP < FCV_LOGOSPEED)
              {              

                // Calculation
                FCL_RSP = FCL_RSP + 1;

              // } else {

              }

            } else {

              // Decision
              if (FCL_RSP > -FCV_LOGOSPEED)
              {              

                // Calculation
                FCL_RSP = FCL_RSP - 1;

              // } else {

              }

            }

          } else {

            // Calculation
            FCL_COUNTER = FCL_COUNTER + 1;

          }

        }

      }

    }

    // Decision
    if (FCL_COUNTER < 8)
    {    

      // Calculation
      FCL_OLDMODE = FCL_MODE;

    } else {

      // Calculation
      FCL_OLDMODE = 10;

    }

  }

  // Calculation
  FCV_LOGOMOVE = 0;

  // Delay
  FCI_DELAYBYTE_MS(50);

#if 0 // Disabled code
  // Call Component Macro
  FCD_0ab21_gLCD_ST7567_SPI1__ClearDisplay();

#endif // Disabled code

#if 0 // Disabled code
  // Call Component Macro
  FCD_0ab21_gLCD_ST7567_SPI1__PrintNumber(FCL_ENCTARGET, 0, 0, 0, 0);

#endif // Disabled code

#if 0 // Disabled code
  // Call Component Macro
  FCD_0ab21_gLCD_ST7567_SPI1__PrintNumber(FCV_ENCCOUNT[0], 0, 16, 0, 0);

#endif // Disabled code

#if 0 // Disabled code
  // Call Component Macro
  FCD_0ab21_gLCD_ST7567_SPI1__PrintNumber(FCV_ENCCOUNT[1], 64, 16, 0, 0);

#endif // Disabled code

#if 0 // Disabled code
  // Delay
  FCI_DELAYBYTE_S(2);

#endif // Disabled code

  //Local variable definitions
  #undef FCLsz_DIR
  #undef FCLsz_ENCCOUNTOLD
}

