/*=----------------------------------------------------------------------=*\
   Use :Allows a Bluetooth AT command to be sent.
       :This macro is private so make sure that all commands are send in Initialise before enabling the Bluetooth RX interrupt.
       :
       :Parameters for macro BluetoothCommand:
       :  Command[20] : MX_CHAR (by-ref)
\*=----------------------------------------------------------------------=*/
void FCM_BluetoothCommand(MX_CHAR *FCL_COMMAND, MX_UINT16 FCLsz_COMMAND)
{
  //Local variable definitions
  #define FCLsz_REPLY 20
  MX_CHAR FCL_REPLY[FCLsz_REPLY];
  MX_UINT8 FCL_IN;


  // Loop
  for (FCLV_LOOP1=0; (FCLV_LOOP1)<(10); (FCLV_LOOP1)++)
  {
    // Call Component Macro
    FCD_06b71_BlueTooth__ReceiveChar(1);

  }

  // Call Component Macro
  FCD_06b71_BlueTooth__SendString(FCL_COMMAND, FCLsz_COMMAND);

  // Call Component Macro
  FCD_06b71_BlueTooth__SendChar('\r');

  // Call Component Macro
  FCD_06b71_BlueTooth__SendChar('\n');

  // Loop
  for (FCLV_LOOP2=0; (FCLV_LOOP2)<(50); (FCLV_LOOP2)++)
  {
    // Call Component Macro
    FCD_06b71_BlueTooth__ReceiveChar(1);

  }

  //Local variable definitions
  #undef FCLsz_REPLY
}

/*=----------------------------------------------------------------------=*\
   Use :Rotates the robot left by a specific angle using the encoders as feedback to ensure
       :the robot turns evenly. Automatically stops at the specified turn angle.
       :
       :Parameters for macro LogoTurnLeft:
       :  Angle : Angle in degrees you wish to rotate. Range 1-65536
\*=----------------------------------------------------------------------=*/
void FCM_LogoTurnLeft(MX_UINT16 FCL_ANGLE)
{
  //Local variable definitions
  MX_UINT32 FCL_ENCTARGET;
  MX_FLOAT FCL_FCALC;


  // Calculation
  FCL_FCALC = flt_fromi(FCL_ANGLE);
  FCL_FCALC = flt_mul(FCL_FCALC, FCV_ANGLERESOLUTION);
  FCL_FCALC = flt_div(FCL_FCALC, FCV_ENCODERRESOLUTION);
  FCL_FCALC = flt_mul(FCL_FCALC, 0.880000);
  FCL_ENCTARGET = flt_toi(FCL_FCALC);

  // Call Macro
  FCM_LogoProcess2(-(FCV_LOGOSPEED * 3) / 4, (FCV_LOGOSPEED * 3) / 4, FCL_ENCTARGET);

}

