      // Simulation
      // .position=::Panel.Position.Get(IROBJ7)

      // Simulation
      // ::Panel.Position.MoveBy(.position, 7.0, -7.0, 0)

      // Calculation
      FCL_X = 0.5;
      FCL_Y = -0.5;

