/*=----------------------------------------------------------------------=*\
   Use :Sets the speed and direction of the Formula Allcode motors.
       :
       :Parameters for macro SetMotorsInterrupt:
       :  Left : Valid Range = -100 to 100
       :  Right : Valid Range = -100 to 100
\*=----------------------------------------------------------------------=*/
void FCM_SetMotorsInterrupt(MX_SINT16 FCL_LEFT, MX_SINT16 FCL_RIGHT)
{
  //Local variable definitions
  MX_UINT8 FCL_MASK = (0x0);


  OC1CON1 = 0;
  OC2CON1 = 0;
  OC5CON1 = 0;
  OC6CON1 = 0;

  // Decision
  if (FCL_LEFT == 0)
  {  

    // Calculation
    FCV_LEFT = 0;

#if 0 // Disabled code
    // Apply Left Brake
    SET_PORT_MASK(D,0x0003,(0x03));

#endif // Disabled code

    // Release Left Brake
    SET_PORT_MASK(D,0x0003,(0));

  } else {

    // Calculation
    FCL_MASK = FCL_MASK | 1;

    // Decision
    if (FCL_LEFT >= 0)
    {    

      // Calculation
      FCV_LEFT = FCL_LEFT;

      // Calculation
      FCV_LEFTDIR = 0;

      // Call Component Macro
      FC_CAL_PWM_Enable_3();

      // Call Component Macro
      FC_CAL_PWM_SetDuty8Bit_3(FCV_LEFT);

    } else {

      // Calculation
      FCV_LEFT = 0 - FCL_LEFT;

      // Calculation
      FCV_LEFTDIR = 1;

      // Call Component Macro
      FC_CAL_PWM_Enable_2();

      // Call Component Macro
      FC_CAL_PWM_SetDuty8Bit_2(FCV_LEFT);

    }

    // Release Left Brake
    SET_PORT_MASK(D,0x0003,(0));

  }

  // Decision
  if (FCL_RIGHT == 0)
  {  

    // Calculation
    FCV_RIGHT = 0;

#if 0 // Disabled code
    // Apply Right Brake
    SET_PORT_MASK(D,0x000C,(0x0C));

#endif // Disabled code

    // Release Right Brake
    SET_PORT_MASK(D,0x000C,(0));

  } else {

    // Calculation
    FCL_MASK = FCL_MASK | 2;

    // Decision
    if (FCL_RIGHT >= 0)
    {    

      // Calculation
      FCV_RIGHT = FCL_RIGHT;

      // Calculation
      FCV_RIGHTDIR = 0;

      // Call Component Macro
      FC_CAL_PWM_Enable_5();

      // Call Component Macro
      FC_CAL_PWM_SetDuty8Bit_5(FCV_RIGHT);

    } else {

      // Calculation
      FCV_RIGHT = 0 - FCL_RIGHT;

      // Calculation
      FCV_RIGHTDIR = 1;

      // Call Component Macro
      FC_CAL_PWM_Enable_4();

      // Call Component Macro
      FC_CAL_PWM_SetDuty8Bit_4(FCV_RIGHT);

    }

    // Release Right Brake
    SET_PORT_MASK(D,0x000C,(0));

  }

}

