/*=----------------------------------------------------------------------=*\
   Use :Reads the analogue value from the specified IR distance sensor.
       :Return value range: 0 to 4095
       :4095 represents the object is very close.
       :
       :Parameters for macro ReadIRSensor:
       :  Channel : Range: 0 to 7 - 0=Left, 1=Front Left, 2=Front, 3=Front Right, 4=Right, 5=Rear Right, 6=Rear, 7=Rear Left
       :
       :Returns : MX_UINT16
\*=----------------------------------------------------------------------=*/
MX_UINT16 FCM_ReadIRSensor(MX_UINT8 FCL_CHANNEL)
{
  //Local variable definitions
  MX_UINT16 FCL_SAMPLEON = (0x0);
  MX_UINT16 FCL_SAMPLEOFF;
  MX_UINT16 FCR_RETVAL;


  // Switch
  switch (FCL_CHANNEL)
  {
    case 1:
    {

      // Call Component Macro
      FCL_SAMPLEOFF = FCD_03525_IR1__GetInt();

      // IR Output On
      SET_PORT_PIN(D,11,(1));

      // Call Component Macro
      FCL_SAMPLEON = FCD_03525_IR1__GetInt();

      // IR Off
      SET_PORT_PIN(D,11,(0));

      break;
    }
    case 2:
    {

      // Call Component Macro
      FCL_SAMPLEOFF = FCD_03526_IR2__GetInt();

      // IR Output On
      SET_PORT_PIN(D,12,(1));

      // Call Component Macro
      FCL_SAMPLEON = FCD_03526_IR2__GetInt();

      // IR Off
      SET_PORT_PIN(D,12,(0));

      break;
    }
    case 3:
    {

      // Call Component Macro
      FCL_SAMPLEOFF = FCD_03527_IR3__GetInt();

      // IR Output On
      SET_PORT_PIN(D,13,(1));

      // Call Component Macro
      FCL_SAMPLEON = FCD_03527_IR3__GetInt();

      // IR Off
      SET_PORT_PIN(D,13,(0));

      break;
    }
    case 4:
    {

      // Call Component Macro
      FCL_SAMPLEOFF = FCD_03528_IR4__GetInt();

      // IR Output On
      SET_PORT_PIN(D,14,(1));

      // Call Component Macro
      FCL_SAMPLEON = FCD_03528_IR4__GetInt();

      // IR Off
      SET_PORT_PIN(D,14,(0));

      break;
    }
    case 5:
    {

      // Call Component Macro
      FCL_SAMPLEOFF = FCD_03529_IR5__GetInt();

      // IR Output On
      SET_PORT_PIN(A,5,(1));

      // Call Component Macro
      FCL_SAMPLEON = FCD_03529_IR5__GetInt();

      // IR Off
      SET_PORT_PIN(A,5,(0));

      break;
    }
    case 6:
    {

      // Call Component Macro
      FCL_SAMPLEOFF = FCD_0352a_IR6__GetInt();

      // IR Output On
      SET_PORT_PIN(A,6,(1));

      // Call Component Macro
      FCL_SAMPLEON = FCD_0352a_IR6__GetInt();

      // IR Off
      SET_PORT_PIN(A,6,(0));

      break;
    }
    case 7:
    {

      // Call Component Macro
      FCL_SAMPLEOFF = FCD_0352b_IR7__GetInt();

      // IR Output On
      SET_PORT_PIN(C,4,(1));

      // Call Component Macro
      FCL_SAMPLEON = FCD_0352b_IR7__GetInt();

      // IR Off
      SET_PORT_PIN(C,4,(0));

      break;
    }
    default:
    {
      // Call Component Macro
      FCL_SAMPLEOFF = FCD_03521_IR0__GetInt();

      // IR Output On
      SET_PORT_PIN(D,8,(1));

      // Call Component Macro
      FCL_SAMPLEON = FCD_03521_IR0__GetInt();

      // IR Off
      SET_PORT_PIN(D,8,(0));

    }
  }

  // Calculation
  FCL_SAMPLEON = 4095 - FCL_SAMPLEON;
  FCL_SAMPLEOFF = 4095 - FCL_SAMPLEOFF;

  // Decision
  if (FCL_SAMPLEON > FCL_SAMPLEOFF)
  {  

    // Calculation
    FCR_RETVAL = FCL_SAMPLEON - FCL_SAMPLEOFF;

  } else {

    // Calculation
    FCR_RETVAL = 0;

  }

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Sets the speed and direction of the Formula Allcode motors.
       :
       :Parameters for macro SetMotors:
       :  Left : Valid Range = -100 to 100
       :  Right : Valid Range = -100 to 100
\*=----------------------------------------------------------------------=*/
void FCM_SetMotors(MX_SINT16 FCL_LEFT, MX_SINT16 FCL_RIGHT)
{
  //Local variable definitions
  MX_UINT8 FCL_MASK = (0x0);


  // Decision
  if ((FCL_LEFT == 0) && (FCL_RIGHT == 0))
  {  

    OC1CON1 = 0;
    OC2CON1 = 0;
    OC5CON1 = 0;
    OC6CON1 = 0;

    // Apply Both Brakes
    SET_PORT_MASK(D,0x000F,(0x0F));

  } else {

    // Decision
    if (FCL_LEFT == 0)
    {    

      OC1CON1 = 0;
      OC5CON1 = 0;

      // Calculation
      FCV_LEFT = 0;

      // Apply Left Brake
      SET_PORT_MASK(D,0x0003,(0x03));

#if 0 // Disabled code
      // Release Left Brake
      SET_PORT_MASK(D,0x0003,(0));

#endif // Disabled code

    } else {

      // Calculation
      FCL_MASK = FCL_MASK | 1;

      // Decision
      if (FCL_LEFT >= 0)
      {      

        // Calculation
        FCV_LEFT = FCL_LEFT;

        // Calculation
        FCV_LEFTDIR = 0;

        OC5CON1 = 0;

        // Call Component Macro
        FC_CAL_PWM_Enable_3();

        // Call Component Macro
        FC_CAL_PWM_SetDuty8Bit_3(FCV_LEFT);

      } else {

        // Calculation
        FCV_LEFT = 0 - FCL_LEFT;

        // Calculation
        FCV_LEFTDIR = 1;

        OC1CON1 = 0;

        // Call Component Macro
        FC_CAL_PWM_Enable_2();

        // Call Component Macro
        FC_CAL_PWM_SetDuty8Bit_2(FCV_LEFT);

      }

      // Release Left Brake
      SET_PORT_MASK(D,0x0003,(0));

    }

    // Decision
    if (FCL_RIGHT == 0)
    {    

      OC2CON1 = 0;
      OC6CON1 = 0;

      // Calculation
      FCV_RIGHT = 0;

      // Apply Right Brake
      SET_PORT_MASK(D,0x000C,(0x0C));

#if 0 // Disabled code
      // Release Right Brake
      SET_PORT_MASK(D,0x000C,(0));

#endif // Disabled code

    } else {

      // Calculation
      FCL_MASK = FCL_MASK | 2;

      // Decision
      if (FCL_RIGHT >= 0)
      {      

        // Calculation
        FCV_RIGHT = FCL_RIGHT;

        // Calculation
        FCV_RIGHTDIR = 0;

        OC6CON1 = 0;

        // Call Component Macro
        FC_CAL_PWM_Enable_5();

        // Call Component Macro
        FC_CAL_PWM_SetDuty8Bit_5(FCV_RIGHT);

      } else {

        // Calculation
        FCV_RIGHT = 0 - FCL_RIGHT;

        // Calculation
        FCV_RIGHTDIR = 1;

        OC2CON1 = 0;

        // Call Component Macro
        FC_CAL_PWM_Enable_4();

        // Call Component Macro
        FC_CAL_PWM_SetDuty8Bit_4(FCV_RIGHT);

      }

      // Release Right Brake
      SET_PORT_MASK(D,0x000C,(0));

    }

  }

  // Decision
  if (0 == 1)
  {  

    // Decision
    if (FCV_LOGOMOVE == 0)
    {    

      // Decision
      if (FCL_MASK == 0)
      {      

        // Motor Encoder Monitor Interrupt Disable
        // Interrupt: Disable TMR8
        IEC3bits.T8IE = 0;
        T8CON = 0;

      } else {

        // Reset Encoder Counters
        FCV_ENCCOUNT[0] = 0;
        FCV_ENCCOUNT[1] = 0;

        // Motor Encoder Monitor Interrupt Enable
        // Interrupt: Enable TMR9 @ 133.514Hz
        T8CON = ((T8CON & 0xfffd) | 0x8000);
        T8CON = ((T8CON & 0xff0f) | 0x0010);
        PR8=65536-1;
        IEC3bits.T8IE = 1;

      }

    // } else {

    }

  // } else {

  }

}

/*=----------------------------------------------------------------------=*\
   Use :Drives the robot backward using the encoders as feedback to ensure
       :the robot drives straight. Automatically stops at the specified distance.
       :
       :Parameters for macro LogoBackwards:
       :  Distance : Distance you want to robot to drive in mm. Range 1-65535
\*=----------------------------------------------------------------------=*/
void FCM_LogoBackwards(MX_UINT16 FCL_DISTANCE)
{
  //Local variable definitions
  MX_UINT32 FCL_ENCTARGET;
  MX_FLOAT FCL_FCALC;


  // Calculation
  FCL_FCALC = flt_fromi(FCL_DISTANCE);
  FCL_FCALC = flt_div(FCL_FCALC, FCV_ENCODERRESOLUTION);
  FCL_FCALC = flt_mul(FCL_FCALC, 1.000000);
  FCL_ENCTARGET = flt_toi(FCL_FCALC);

  // Call Macro
  FCM_LogoProcess2(-FCV_LOGOSPEED, -FCV_LOGOSPEED, FCL_ENCTARGET);

}

