/*=----------------------------------------------------------------------=*\
   Use :Starts up the Formula Allcode PWM for motor control and performs the wait for button press if enabled.
\*=----------------------------------------------------------------------=*/
void FCM_Initialise()
{
  //Local variable definitions
  MX_UINT8 FCL_SW = (0x0);
  #define FCLsz_CMD 20
  MX_CHAR FCL_CMD[FCLsz_CMD];
  MX_UINT16 FCL_TEST;


  // Calculation
  FCL_SW = 0;
  FCI_SCOPY("",1, FCL_CMD,FCLsz_CMD);

  // Calculation
  FCV_RESETCOUNT = 0;
  FCV_AREYOUTHERECOUNT = 0;
  FCV_CMDACTIVE = 0;

  // Wait for PLL to lock
  FCI_DELAYBYTE_MS(10);

  //Comment:
  //Initialise Motors

  // Init Motor Dir Pins
  SET_PORT_MASK(D,0x000F,(0x00));

  // Init Prescalers
  FC_CAL_PWM_ChangePeriod_2(100, 8);

  // Enable Motor Driver
  SET_PORT_PIN(G,7,(1));

  // Simulation
  // ::Connection.SetAn(21, 0.606, 0)

  //Comment:
  //Initialise LCD

  // Call Component Macro
  FCD_0ab21_gLCD_ST7567_SPI1__Initialise();

  // Call Component Macro
  FCD_0ab21_gLCD_ST7567_SPI1__ClearDisplay();

  // Call Component Macro
  FCD_0ab21_gLCD_ST7567_SPI1__Print("Formula AllCode", 16, 18, 0, 0, 0);

  // Decision
  if ((3 == 2) | (3 == 3))
  {  

    // Call Component Macro
    FCD_092a1_AutoVersionID1__GetDate(FCL_CMD,20 );

    // Call Component Macro
    FCD_0ab21_gLCD_ST7567_SPI1__Print(FCL_CMD, FCLsz_CMD, 5, 8, 0, 0);

  // } else {

  }

  // Decision
  if ((3 == 1) | (3 == 3))
  {  

    // Call Component Macro
    FCD_092a1_AutoVersionID1__GetTime(FCL_CMD,20 );

    // Call Component Macro
    FCD_0ab21_gLCD_ST7567_SPI1__Print(FCL_CMD, FCLsz_CMD, 75, 8, 0, 0);

  // } else {

  }

#if 0 // Disabled code
  // Call Macro
  FCM_BattMon();

#endif // Disabled code

  //Comment:
  //Initialise backlight

  // Call Macro
  FCM_LCDBacklight(50);

  // Call Component Macro
  FCD_06b71_BlueTooth__Initialise();

  //Comment:
  //Enable Interrupts

  // Calculation
  FCV_ENCSAVE = GET_PORT(B) >> 11;

  // Bluetooth RX Interrupt Enable
  // Interrupt: Enable RXINT0
  IEC0bits.U1RXIE = 1;

  // Encoder Interrupt Enable
  // Interrupt: Enable IOC0
  CNENA = 0x0;
  CNENB = 0x1800;
  CNENC = 0x0;
  CNEND = 0x0;
  CNENE = 0x0;
  CNENF = 0x0;
  CNENG = 0x0;
  IEC1bits.CNIE = 1;

  //Comment:
  //Restore Logo Resultion From Flash EE memory

  // Call Macro
  FCD_0ee91_flasheeprom1__Initialise();

  // Check to see if the defaults have changed
  FCL_TEST = FCD_0ee91_flasheeprom1__Read(20);

  // Decision
  if (FCL_TEST == 0)
  {  

    // Load new default Distance
    FCV_ENCODERRESOLUTION = FCM_GetEEFloat(0);

    // Load new default angle
    FCV_ANGLERESOLUTION = FCM_GetEEFloat(10);

    // Load motor calibration
    FCM_Prv_LoadMotorCal();

  // } else {

  }

  //Comment:
  //Wait for switch

  // Wait for switch press?
  if (1 == 1)
  {  

    // Call Component Macro
    FCD_0ab21_gLCD_ST7567_SPI1__Print("Waiting For Switch", 19, 8, 24, 0, 0);

    // Loop
    while (FCL_SW == 0)
    {
#if 0 // Disabled code
      // Call Macro
      FCM_BattMon();

#endif // Disabled code

      // Input
      FCL_SW = GET_PORT_MASK(A,0x0003);

      // Delay
      FCI_DELAYBYTE_MS(20);

    }

    // Call Component Macro
    FCD_0ab21_gLCD_ST7567_SPI1__Print("                  ", 19, 8, 16, 0, 0);

    // Delay
    FCI_DELAYBYTE_MS(50);

    // Loop
    while (FCL_SW > 0)
    {
      // Input
      FCL_SW = GET_PORT_MASK(A,0x0003);

    }

  } else {

    // Delay
    FCI_DELAYINT_MS(2000);

  }

  // Call Component Macro
  FCD_0ab21_gLCD_ST7567_SPI1__ClearDisplay();

  // Call Macro
  FCM_LCDBacklight(0);

  // Decision
  if (0)
  {  

    // Call Macro
    FCM_SetMotorsInterrupt(0, 0);

  // } else {

  }

  //Local variable definitions
  #undef FCLsz_CMD
}

